INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8c8d-7444-b13b-5bf17fee9465'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'Simplify (p - 3n)(4n - 1) / [12n(4n - 1)].', '(3n - p)/(12n)', 'Cancel the common factor (4n - 1) from numerator and denominator. Since p - 3n = -(3n - p), the expression becomes (3n - p)/(12n).', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.685Z'::timestamptz, '2026-08-15T07:36:12.685Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8ca2-7a4a-a146-58df5bcef9cb'::uuid, '019f9df7-a2a2-77cc-bb88-40ce254805a8'::uuid, 'The green and red lights flash every 6 seconds and 8 seconds respectively. If they start together, how long will it take for them to next flash simultaneously?', '24 s', 'Find the least common multiple of 6 and 8. LCM(6, 8) = 24, so they will next flash together after 24 seconds.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.706Z'::timestamptz, '2026-08-15T07:36:12.706Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8cb6-7d56-8d02-0771e5f0e07f'::uuid, '019f9df7-a2a2-77cc-bb88-40ce254805a8'::uuid, 'Express 2250 as a product of its prime factors.', '2 × 3^2 × 5^3', '2250 = 225 × 10 = (3^2 × 5^2) × (2 × 5) = 2 × 3^2 × 5^3.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.726Z'::timestamptz, '2026-08-15T07:36:12.726Z'::timestamptz) ON CONFLICT (id) DO NOTHING;